#include "info.h"

#include <stdio.h>

#ifndef APP_VERSION
#define APP_VERSION "unknown"
#endif

void info_build_string(char *buf, size_t bufsize) {
    snprintf(buf, bufsize, "build %s", APP_VERSION);
}

